      diff: corrected.diff,
      gf: corrected.gf,
      gm: corrected.gm,
      flags: corrected.flags,
      gear: corrected.gear,
      effectiveEquipNorm: corrected.effectiveEquipNorm,
      motor,
      coordination,
      plyometric,
      sourceHash: hash,
