    if (error.message === "\u0422\u043E\u0437\u0438 \u043F\u0440\u043E\u0434\u0443\u043A\u0442 \u0432\u0435\u0447\u0435 \u0441\u044A\u0449\u0435\u0441\u0442\u0432\u0443\u0432\u0430 \u0432 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430") {
      return jsonResponse2({ error: error.message }, 409);
    }
    return jsonResponse2({ error: error.message || "\u041D\u0435\u0443\u0441\u043F\u0435\u0448\u043D\u0430 \u0440\u0435\u0434\u0430\u043A\u0446\u0438\u044F \u043D\u0430 \u043F\u0440\u043E\u0434\u0443\u043A\u0442" }, 500);
