    macroGrams: analysis.macroGrams ? `P${analysis.macroGrams.protein ?? "?"}g/C${analysis.macroGrams.carbs ?? "?"}g/F${analysis.macroGrams.fats ?? "?"}g` : "\u043D\u0435 \u0438\u0437\u0447\u0438\u0441\u043B\u0435\u043D\u0438"
