async function finalizeValidatedPlan(env, structuredPlan, data) {
  await reconcilePlanStructure(structuredPlan, data, env);
  const foodLists = await getDynamicFoodListsSections(env);
  const validation = validatePlan(structuredPlan, data, foodLists.dynamicSubstitutions || []);
  if (!structuredPlan.generationWarnings) structuredPlan.generationWarnings = [];
  const coherenceIssues = validateWeekPlanDayCoherence(structuredPlan.weekPlan || {});
  const varietyResult = validateWeeklyDishVariety(structuredPlan.weekPlan || {});
  if (coherenceIssues.length) validation.warnings = [...validation.warnings || [], ...coherenceIssues];
  if (varietyResult.issues.length) {
    validation.warnings = [...validation.warnings || [], ...varietyResult.issues];
  }
  if (validation.warnings?.length) {
    structuredPlan.generationWarnings.push(...validation.warnings);
  }
  if (validation.errors?.length) {
    structuredPlan.generationWarnings.push(...validation.errors);
  }
  if (validation.blockingErrors?.length) {
    throw new Error(`\u041F\u043B\u0430\u043D\u044A\u0442 \u043D\u0435 \u043C\u0438\u043D\u0430\u0432\u0430 \u043C\u0435\u0434\u0438\u0446\u0438\u043D\u0441\u043A\u0438 \u043F\u0440\u0430\u0433\u043E\u0432\u0435: ${validation.blockingErrors.join("; ")}`);
  }
  if (structuredPlan.generationWarnings.length) {
    console.log(`Plan post-validation: ${structuredPlan.generationWarnings.length} warning(s)`);
  }
  if (finalDirectorEnabled(env)) {
    try {
      const director = await runFinalDirectorReview(env, structuredPlan, data, validation);
      if (director?.verdict === "REJECT") {
        structuredPlan.directorRejected = true;
        structuredPlan.generationWarnings.push(
          `Step 6: \u043F\u043B\u0430\u043D\u044A\u0442 \u0435 \u043E\u0442\u0445\u0432\u044A\u0440\u043B\u0435\u043D \u043E\u0442 \u0444\u0438\u043D\u0430\u043B\u043D\u0438\u044F \u043F\u0440\u0435\u0433\u043B\u0435\u0434 \u2014 ${(director.coherenceNotes || []).join("; ") || "\u0431\u0435\u0437 \u0434\u0435\u0442\u0430\u0439\u043B\u0438"}`
        );
      }
    } catch (directorErr) {
      console.warn("Step 6 Final Director skipped:", directorErr.message);
    }
  }
  return validation;
}
async function generatePlanCore(env, data, onAnalysisReady = null) {
  await loadCatalogRegistryOverlay(env);
  const userId = data.email || generateUserId(data);
  const adherenceRatio = await loadAdherenceRatioForGeneration(env, data, userId);
  if (adherenceRatio?.size) data._adherenceRatio = adherenceRatio;
  const clinicalProtocol = getClinicalProtocol(data.clinicalProtocol);
  if (clinicalProtocol) {
    if (data.clinicalProtocol === "postpartum_lactation" && data.postpartumGoal) {
      data.goal = Array.isArray(data.postpartumGoal) ? data.postpartumGoal.join(" + ") : data.postpartumGoal;
    }
    if (!data.goal) data.goal = clinicalProtocol.goalMapping;
    if (!data.medicalConditions || data.medicalConditions.length === 0) {
      data.medicalConditions = [clinicalProtocol.name];
    }
  }
  const valConfig = await getValidationConfig(env);
  const dataValidation = validateDataAdequacy(data, valConfig);
  if (!dataValidation.isValid) {
    const err = (
      /** @type {any} */
      new Error(dataValidation.errorMessage)
    );
    err.validationFailed = true;
    throw err;
  }
  const { hasContradiction, canProceed: contradictionCanProceed, warningData } = detectGoalContradiction(data, valConfig);
  if (hasContradiction && !contradictionCanProceed) {
    return { success: true, hasContradiction: true, warningData, userId };
  }
  enrichUserDataEngineContext(data);
  let structuredPlan = await generatePlanMultiStep(env, data, onAnalysisReady);
  try {
    await finalizeValidatedPlan(env, structuredPlan, data);
  } catch (validationErr) {
    if (validationErr.message?.includes("\u043C\u0435\u0434\u0438\u0446\u0438\u043D\u0441\u043A\u0438 \u043F\u0440\u0430\u0433\u043E\u0432\u0435")) throw validationErr;
    console.warn("Plan post-validation skipped:", validationErr.message);
  }
  const correctionAttempts = 0;
  const cleanPlan = removeInternalJustifications(structuredPlan);
  if (clinicalProtocol && clinicalProtocol.hacks) {
    cleanPlan.hacks = clinicalProtocol.hacks;
  } else {
    cleanPlan.hacks = await getGoalHacks(env, data.goal);
  }
  if (clinicalProtocol) cleanPlan.clinicalProtocol = { id: clinicalProtocol.id, name: clinicalProtocol.name };
  return { success: true, plan: cleanPlan, userId, correctionAttempts };
}
